<?php require_once __DIR__ . '/../includes/functions.php'; require_once __DIR__ . '/../includes/database.php'; admin_required(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf_token']??null)){ $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';if($id&&in_array($action,['read','unread','delete'],true)){if($action==='delete')$pdo->prepare('DELETE FROM contact_messages WHERE id=?')->execute([$id]);else $pdo->prepare('UPDATE contact_messages SET status=? WHERE id=?')->execute([$action,$id]);}header('Location: messages.php');exit;} $view=filter_input(INPUT_GET,'view',FILTER_VALIDATE_INT);if($view){$pdo->prepare("UPDATE contact_messages SET status='read' WHERE id=?")->execute([$view]);$stmt=$pdo->prepare('SELECT * FROM contact_messages WHERE id=?');$stmt->execute([$view]);$message=$stmt->fetch();} $messages=$pdo->query('SELECT * FROM contact_messages ORDER BY id DESC')->fetchAll(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages | VeytronaTech Admin</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header scrolled"><div class="nav shell"><a class="brand" href="dashboard.php"><span class="brand-mark">V</span><span>VEYTRONA<span>TECH</span></span></a><nav class="nav-links" style="display:flex"><a href="dashboard.php">Dashboard</a><a href="logout.php">Logout</a></nav></div></header><main class="shell"><section class="page-hero"><p class="eyebrow">Admin</p><h1>Messages</h1></section><?php if(isset($message)&&$message): ?><section class="form-card" style="margin-bottom:30px"><p class="eyebrow"><?=e($message['project_type'])?> · <?=e($message['created_at'])?></p><h2 style="font-family:'Space Grotesk'"><?=e($message['name'])?></h2><p class="muted"><?=e($message['email'])?><?= $message['company']?' · '.e($message['company']):'' ?></p><p><?=nl2br(e($message['message']))?></p></section><?php endif ?><section class="form-card" style="overflow:auto"><table class="admin-table"><thead><tr><th>Contact</th><th>Project</th><th>Message</th><th>Action</th></tr></thead><tbody><?php foreach($messages as $m): ?><tr><td><a href="?view=<?=$m['id']?>"><?=e($m['name'])?></a><br><span class="muted"><?=e($m['email'])?></span></td><td><?=e($m['project_type'])?><br><span class="muted"><?=e($m['budget'])?></span></td><td><?=e(mb_strimwidth($m['message'],0,80,'…'))?></td><td><form method="post" class="admin-actions"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><button name="action" value="<?=$m['status']==='read'?'unread':'read'?>"><?=$m['status']==='read'?'Mark unread':'Mark read'?></button><button name="action" value="delete" onclick="return confirm('Delete this message permanently?')">Delete</button></form></td></tr><?php endforeach ?><?php if(!$messages): ?><tr><td colspan="4">No messages yet.</td></tr><?php endif ?></tbody></table></section></main></body></html>
